INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.122.1',
  '2026-10-23',
  'Пульт ТВ: в браузере компьютера видно, что файл не играет; папка «anime» у сторожа',
  E'Аниме, уехавшее на приставку в x265, на телевизоре играет, а в браузере на компьютере открывалось со звуком и чёрным экраном: HEVC в Chrome и Firefox под Linux не поддерживается вовсе. Теперь страница спрашивает кодеки у того браузера, в котором открыта, и такой файл помечает прямо в списке: «⚠ hevc не играет в этом браузере — нажмите, чтобы перекодировать». Нажатие ставит обычную фоновую задачу, и после неё серия играется на обоих экранах.\n\nУ папки «положил и забыл» появилась **третья подпапка — `anime`**: что положили в неё, уезжает в раздел «Аниме» (раньше были только `films` и `serials`).\n\nПри отправке hevc по-прежнему копируется как есть — это быстро и без потерь, а приставка его играет; но план теперь говорит, что смотреть такое можно только на телевизоре, а ключ `--h264` перекодирует сразу для всех экранов.',
  E'Страница: `screenCodecs` (один `canPlayType` на загрузку страницы: hevc по hvc1/hev1, av1, vp9) и `codecHere(it)` — ими уточняется вердикт агента в `playable()` и `verdictTag()`. Вердикт в `library.go` остался прежним: он про приставку (Xiaomi, Chrome в WebView, берёт hevc и 10 бит), а экранов у агента два. `transcode(it)` при «агент считает годным, а здесь не играет» просит профиль `video` явно — иначе `addJob` взял бы вердикт `ok` и перепаковал контейнер, что ничего бы не изменило.\n\nПричина: `COPY_VIDEO` в `send-series.py` копирует hevc, и 48 серий «Аптекарши» (x265 Main 10, 10 бит) уехали как есть. В Chrome 136 на Linux `canPlayType` пуст для `hvc1` и `hev1` в 8 и 10 бит; файл при этом грузится без ошибки (`loadeddata`, duration 2.04), а `videoWidth` остаётся нулём — то есть «звук есть, картинки нет». Воспроизведено локально на тестовой библиотеке из двух клипов (hevc 10 бит и h264) и проверено на res-i3 на самой «Аптекарше».\n\nsend-series.py: `--h264` (force_h264 в `plan_file`) и `-tag:v hvc1` при копировании hevc — ffmpeg по умолчанию ставит `hev1`, которого не берут и браузеры с HEVC (Safari, Chrome на Windows и Mac); в плане у копии hevc появился хвост «играет только на приставке, в браузере компьютера нет — --h264».\n\nconvert-watch.py: третья подпапка `anime` (`scan`, `dest_root` через `anime_dest`, `destinations`, `--anime` в `send_args`, создание папки при старте). Проверено прогоном `--dry-run` на тестовой папке: команда с `--anime`, корень `/mnt/mybook/rudb/media/anime`, пути проверки доставки совпадают.'
);
-- +goose StatementEnd

